"""The user's 2–10 episodes, with ambiguous drafting notes resolved."""
import json
from pathlib import Path

games=[]
def game(id,unit,title,icon,theme,intro,ending,rows):
    questions=[]
    for index,row in enumerate(rows,1):
        skill,name,prompt,answer,explanation,hint,*diagram=row
        questions.append(dict(id=f'{id}-{index}',skill=skill,title=name,prompt=prompt,answer=str(answer),explanation=explanation,hint=hint,diagram=diagram[0] if diagram else ''))
    assert len(questions)==10
    games.append(dict(id=id,unit=unit,title=title,icon=icon,theme=theme,intro=intro,ending=ending,questions=questions))

game(1,'소인수분해','고대 수학 박물관과 황금 금고의 비밀','🏛️','museum',
"삐익— 삐익—! 박물관 보안 시스템이 가동되었습니다. ‘피타고라스의 황금 열쇠’를 구경하던 당신은 실수로 전시실에 갇혔습니다. 고대 수학자들이 설계한 10개의 보안 장치를 순서대로 복구해 황금 금고를 열고 박물관을 탈출하세요!",
"찰칵—! 황금 금고가 열리고 피타고라스의 황금 열쇠가 눈부시게 빛납니다. 열쇠를 출입문에 꽂자 박물관의 문이 활짝 열렸습니다! 10개의 보안 장치를 모두 해결하고 첫 번째 탐험을 완료했습니다.",[
('거듭제곱의 뜻','박물관 입구 보안패드','입구 키패드에 3+3+3+3=a, 2×2×2×2×2=2ᵇ라는 암호가 나타났습니다. 자연수 a와 b의 합 a+b를 입력하세요.',17,'a=3×4=12이고, 2를 다섯 번 곱했으므로 b=5입니다. 따라서 a+b=12+5=17입니다.','같은 수를 더한 횟수와 곱한 횟수를 구분해 보세요. 거듭제곱의 지수는 곱한 횟수예요.'),
('거듭제곱의 계산','꺼진 전시실 조명','전시실에 전기를 공급하려면 2⁴+3²의 값을 조명 장치에 입력해야 합니다. 알맞은 수를 구하세요.',25,'2⁴=16, 3²=9이므로 16+9=25입니다.','거듭제곱을 각각 계산한 뒤 더하세요.'),
('소수와 합성수','진짜 보석 감별기','보석 번호는 1, 2, 9, 13, 21, 29입니다. 소수 번호가 적힌 보석만 골랐을 때, 선택한 보석은 모두 몇 개인가요?',3,'2, 13, 29가 소수이므로 모두 3개입니다. 1은 소수도 합성수도 아니고, 9와 21은 합성수입니다.','소수는 1보다 큰 자연수 중 약수가 1과 자기 자신뿐인 수예요.'),
('소인수 찾기','고대 석판의 봉인','석판에 적힌 수 84의 서로 다른 소인수를 모두 찾아 그 합을 입력하세요.',12,'84=2²×3×7입니다. 서로 다른 소인수는 2, 3, 7이므로 합은 12입니다.','작은 소수부터 나누어 보세요. 같은 소인수는 한 번만 더해요.'),
('소인수분해','비밀 계단의 암호','72를 소인수분해하면 2ᵃ×3ᵇ입니다. 자연수 a와 b의 합 a+b를 구하세요.',5,'72=2×2×2×3×3=2³×3²이므로 a=3, b=2이고 합은 5입니다.','곱해진 2의 개수와 3의 개수를 각각 세어 지수로 나타내요.'),
('제곱수 만들기','거울 방의 완전한 문양','자연수 45에 어떤 자연수를 곱해 자연수의 제곱을 만들려고 합니다. 곱할 수 있는 가장 작은 자연수를 입력하세요.',5,'45=3²×5입니다. 소인수의 지수가 모두 짝수가 되어야 하므로 5를 한 번 더 곱합니다. 45×5=225=15²입니다.','자연수의 제곱에서는 소인수분해한 각 소수의 지수가 모두 짝수예요.'),
('약수의 개수','수학자의 서랍 열기','120을 소인수분해하여 120의 양의 약수의 개수를 구하세요. 이 개수가 서랍의 비밀번호입니다.',16,'120=2³×3×5이므로 양의 약수의 개수는 (3+1)(1+1)(1+1)=4×2×2=16개입니다.','각 소인수의 지수에 1을 더한 수들을 곱해요.'),
('최대공약수','쌍둥이 톱니바퀴 정렬','두 톱니바퀴에 36과 48이 새겨져 있습니다. 두 수의 최대공약수를 구해 정렬 장치에 입력하세요.',12,'36=2²×3², 48=2⁴×3입니다. 공통 소인수의 작은 지수를 택하면 최대공약수는 2²×3=12입니다.','두 수에 공통으로 들어 있는 소인수를 찾아요.'),
('최소공배수','두 경보등의 동시 점멸','첫 경보등은 12초마다, 둘째 경보등은 18초마다 켜집니다. 지금 동시에 켜졌다면 몇 초 후 처음으로 다시 동시에 켜질까요?',36,'12=2²×3, 18=2×3²이므로 최소공배수는 2²×3²=36입니다. 36초 후 다시 동시에 켜집니다.','두 경보등의 반복 시간이 만나는 가장 작은 양의 공배수를 구하세요.'),
('최대공약수·최소공배수의 활용','황금 금고의 마지막 잠금!','붉은 보석 24개와 푸른 보석 36개를 남김없이 최대한 많은 꾸러미로 나눕니다. 각 꾸러미에는 색깔별로 같은 수의 보석을 넣어야 합니다. 꾸러미 수를 n, 한 꾸러미의 보석 수를 k라 할 때 최종 코드 n+k를 구하세요.',17,'가장 많은 꾸러미 수 n은 24와 36의 최대공약수인 12입니다. 한 꾸러미에는 붉은 보석 2개와 푸른 보석 3개, 모두 k=5개가 들어갑니다. 따라서 n+k=12+5=17입니다.','최대한 많은 같은 꾸러미의 개수는 최대공약수로 구해요. 이어서 한 꾸러미의 두 색 보석 수를 더하세요.')])

game(2,'정수와 유리수','심해 잠수정 네모호, 마리아나 해구 탈출 대작전','🌊','ocean',
"심해 탐사선 ‘네모호’가 해저 1,000m 협곡에 갇혔습니다! 산소가 바닥나기 전에 10개의 수압 밸브와 엔진 장치를 복구해 해수면으로 부상하세요!",
"푸슈욱—! 네모호가 마침내 푸른 바다 위로 떠올랐습니다! 눈부신 햇살과 함께 2단계 탈출에 성공했습니다.",[
('양수와 음수의 뜻','수심 계기판 복구','해수면(0m)을 기준으로 해발 300m를 +300으로 나타냅니다. 해저 500m 지점을 A, 해발 150m 지점을 B로 나타낼 때, A+B를 입력하세요.',-350,'A=−500, B=+150이므로 −500+150=−350입니다.','해수면보다 아래는 음수, 위는 양수로 나타내요.'),
('정수와 유리수 분류','산소통 밸브 열기','비상 산소통에 적힌 수는 −3, 0, +2.5, −7/2, +8, 12/3입니다. 정수가 적힌 밸브만 열 때, 열어야 할 밸브는 모두 몇 개인가요?',4,'−3, 0, +8, 12/3(=4)가 정수이므로 모두 4개입니다.','분수 모양이라도 계산하면 정수가 될 수 있어요. 0도 정수예요.'),
('수직선과 절댓값','잠수정 균형 잡기','원점에서 거리가 7인 두 지점 중 양수를 a, −5의 절댓값을 b라 할 때, a+b를 입력하세요.',12,'a=7, b=5이므로 a+b=12입니다.','절댓값은 수직선에서 원점까지의 거리예요.'),
('수의 대소 관계','수압 방어벽 가동','−4, +3, −7, 0, +5 중 가장 큰 수를 M, 가장 작은 수를 m이라 할 때, |M|+|m|을 입력하세요.',12,'M=5, m=−7이므로 |5|+|−7|=5+7=12입니다.','먼저 가장 큰 수와 가장 작은 수를 찾고, 각각의 절댓값을 구해요.'),
('유리수의 덧셈','제1엔진 점화','연료 주입량 계산식 (−8)+(+13)+(−2)의 값을 입력하세요.',3,'−8+13−2=5−2=3입니다.','양수끼리, 음수끼리 모으거나 왼쪽부터 차례로 계산해 보세요.'),
('유리수의 뺄셈','해저 수온 조절기','잠수정 외부 온도는 −12°C, 내부 온도는 +18°C입니다. 내부 온도에서 외부 온도를 뺀 온도 차이(°C)를 입력하세요.',30,'18−(−12)=18+12=30입니다.','음수를 빼는 것은 그 수의 부호를 바꿔 더하는 것과 같아요.'),
('덧셈과 뺄셈의 혼합 계산','고장 난 나침반 수리','나침반 오차 수정식 −6+10−(−4)−15의 값을 입력하세요. 음수라면 − 기호를 포함하세요.',-7,'−6+10+4−15=4+4−15=−7입니다.','괄호 앞의 빼기를 먼저 덧셈으로 바꿔 보세요.'),
('유리수의 곱셈과 거듭제곱','프로펠러 회전수 설정','프로펠러 가동식 (−2)³×(−3)×(+2)의 값을 입력하세요.',48,'(−2)³=−8, (−8)×(−3)×2=24×2=48입니다.','거듭제곱을 먼저 계산한 뒤 곱셈의 부호를 결정해요.'),
('역수와 나눗셈','심해 암초 폭파 레이저','−3/4의 역수에 −12를 곱한 값을 조준기에 입력하세요.',16,'−3/4의 역수는 −4/3이므로 (−4/3)×(−12)=16입니다.','역수는 곱해서 1이 되는 수예요.'),
('사칙연산 혼합 계산','해수면 급속 부상 스위치!','마지막 부상 스위치입니다! 10−{(−2)²+(−12)÷3}×5의 값을 입력하세요.',10,'10−{4+(−4)}×5=10−0×5=10입니다.','거듭제곱, 나눗셈, 괄호 안, 곱셈 순서를 지켜 계산해요.')])

game(3,'문자의 사용과 식','마법 약초 상점의 비밀 레시피 해독','🧪','magic',
"대마법사의 약초 상점에서 실수로 ‘투명 인간 물약’을 마셨습니다! 마법이 영원히 굳어지기 전에 10개의 문자 암호 레시피를 해독해 해독제를 만드세요!",
"보글보글— 펑! 보랏빛 연기와 함께 원래 모습으로 돌아왔습니다! 완벽한 계산으로 해독제 조제에 성공했습니다.",[
('곱셈 기호의 생략','약초 선반의 암호','x×(−4)×y를 곱셈 기호를 생략하여 나타냈을 때, 문자 앞의 수인 계수를 입력하세요.',-4,'x×(−4)×y=−4xy이므로 계수는 −4입니다.','수는 문자 앞에 쓰고, 문자들은 알파벳 순서로 나타내요.'),
('나눗셈 기호의 생략과 식의 값','마법 샘물 계량','(a+b)÷3에 a=10, b=8을 대입하여 물의 양(mL)을 구하세요.',6,'(10+8)/3=18/3=6입니다.','괄호 안에 값을 대입해 더한 후 3으로 나누어요.'),
('대입과 음수의 거듭제곱','불꽃 가루 조합','x=−3일 때 화력 식 2x²−5x의 값을 구하세요.',33,'2×(−3)²−5×(−3)=18+15=33입니다.','음수를 대입할 때는 괄호를 써요. x²부터 계산하세요.'),
('항·계수·상수항','고대 마법서의 첫 페이지','4x−7y−9에서 x의 계수를 a, y의 계수를 b, 상수항을 c라 할 때 a+b+c를 입력하세요.',-12,'a=4, b=−7, c=−9이므로 4−7−9=−12입니다.','항 앞의 부호까지 함께 읽어야 해요.'),
('일차식 찾기','진짜 마법 지팡이 감별','① 3x−5  ② x²+2x  ③ 4/x+1  ④ 7  ⑤ (−1/2)y+3\n이 중 일차식인 지팡이는 모두 몇 개인가요?',2,'①과 ⑤가 일차식입니다. ②는 이차식, ③은 다항식이 아니며, ④는 상수입니다.','일차식은 정리했을 때 문자의 차수가 1인 다항식이에요.'),
('일차식과 수의 곱셈','황금 가마솥 온도 증폭','−3(2x−5)를 전개했을 때 x의 계수와 상수항의 합을 입력하세요.',9,'−3(2x−5)=−6x+15이므로 −6+15=9입니다.','괄호 안의 모든 항에 −3을 곱하세요.'),
('동류항의 계산','두 가지 물약 섞기','(5x−3)+(−2x+11)을 ax+b로 나타낼 때 a+b를 입력하세요.',11,'3x+8이므로 a=3, b=8, a+b=11입니다.','문자가 같은 항끼리, 상수항끼리 계산해요.'),
('일차식의 뺄셈','독성 제거 주문','(6x+4)−2(x−5)를 간단히 정리했을 때의 상수항을 입력하세요.',14,'6x+4−2x+10=4x+14이므로 상수항은 14입니다.','−2를 괄호 안의 두 항에 각각 곱해요.'),
('복잡한 일차식의 계산','마력 농축기 가동','{(3x−1)/2−(x−5)/3}에 6을 곱하여 ax+b로 나타낼 때 a+b를 입력하세요.',14,'3(3x−1)−2(x−5)=9x−3−2x+10=7x+7이므로 합은 14입니다.','6을 각 분수 항에 곱하면 분모가 없어져요.'),
('도형과 문자의 식','해독제 결정체 완성!','가로가 4, 세로가 2x+3인 직사각형 마법진의 넓이를 x=3일 때 구하세요.',36,'4×(2×3+3)=4×9=36입니다.','직사각형의 넓이는 가로×세로예요.')])

game(4,'일차방정식','명탐정 셜록, 사라진 다이아몬드와 x의 행방','🔍','detective',
"런던 왕실 박물관에서 ‘블루 다이아몬드’가 사라졌습니다. 괴도 루팡이 남긴 10장의 도전장 속 미지수 x를 추적해 다이아몬드를 되찾으세요!",
"찾았다! 시계탑 비밀 금고 속 블루 다이아몬드가 빛을 발합니다! 명탐정의 추리로 사건을 완벽히 해결했습니다.",[
('방정식과 항등식','루팡의 첫 번째 메모','모든 x에 대해 3x+a=bx−5가 항상 성립합니다. a+b를 구하세요.',-2,'x의 계수와 상수항을 비교하면 b=3, a=−5이므로 합은 −2입니다.','항등식에서는 같은 문자 항의 계수와 상수항이 각각 같아요.'),
('등식의 성질','비밀 금고의 저울','2x−5=9의 양변에 5를 더한 뒤 양변을 2로 나누어 해 x를 구하세요.',7,'2x=14이므로 x=7입니다.','등식의 양변에 같은 연산을 하면 등식이 유지돼요.'),
('이항을 이용한 풀이','베이커가의 가로등 번호','5x−8=2x+10을 풀어 가로등 번호 x를 구하세요.',6,'5x−2x=10+8, 3x=18이므로 x=6입니다.','문자 항은 한쪽으로, 상수항은 반대쪽으로 모아요.'),
('괄호가 있는 일차방정식','암호 해독 타자기','3(x−2)=2(x+4)를 만족하는 x를 입력하세요.',14,'3x−6=2x+8이므로 x=14입니다.','양변의 괄호를 먼저 풀어 보세요.'),
('계수가 소수인 일차방정식','깨진 회중시계의 바늘','0.3x−0.5=0.1x+0.7을 만족하는 x를 구하세요.',6,'양변에 10을 곱하면 3x−5=x+7, 2x=12이므로 x=6입니다.','양변에 10을 곱하면 소수 계수가 정수가 돼요.'),
('계수가 분수인 일차방정식','기차역 물품보관함 열쇠','(x+1)/2−(x−2)/3=2를 만족하는 x를 입력하세요.',5,'양변에 6을 곱하면 3(x+1)−2(x−2)=12, x+7=12이므로 x=5입니다.','분모 2와 3의 최소공배수를 양변에 곱해요.'),
('비례식과 일차방정식','지도 위의 축척 암호','(x+2):6=(x−1):4를 만족하는 x를 구하세요.',7,'4(x+2)=6(x−1), 4x+8=6x−6이므로 x=7입니다.','비례식의 외항의 곱과 내항의 곱은 같아요.'),
('연속하는 자연수 활용','지하실 계단의 비밀번호','연속하는 세 자연수의 합이 48입니다. 가장 큰 수를 입력하세요.',17,'가운데 수를 x라 하면 (x−1)+x+(x+1)=48, x=16입니다. 가장 큰 수는 17입니다.','세 수를 x−1, x, x+1로 나타내면 편리해요.'),
('과부족 활용','공범들의 은화 나누기','은화를 한 사람에게 5개씩 주면 3개가 남고, 6개씩 주면 2개가 부족합니다. 공범은 몇 명인가요?',5,'공범 수를 x라 하면 5x+3=6x−2이므로 x=5입니다.','두 경우의 전체 은화 수를 각각 식으로 나타내어 같다고 놓아요.'),
('거리·속력·시간 활용','루팡의 도주 경로 차단!','루팡이 시속 4km로 걸어간 지 15분 후, 셜록이 같은 지점에서 시속 6km로 추격했습니다. 셜록이 출발한 지 몇 분 뒤에 따라잡을까요?',30,'셜록의 추격 시간을 x시간이라 하면 4×(1/4)+4x=6x, x=1/2시간=30분입니다.','루팡이 먼저 간 거리와 추격 중 간 거리를 더해 셜록의 거리와 같게 놓아요.')])

game(5,'좌표평면과 그래프','우주 정거장 알파, 미지의 행성 불시착 탈출기','🚀','space',
"소행성 충돌로 우주선이 미지의 행성에 불시착했습니다. 레이더 좌표계를 복구하고 정비례·반비례 엔진 출력을 맞춰 우주로 귀환하세요!",
"3, 2, 1, 점화! 쿠구구궁—! 우주선이 대기권을 뚫고 무사히 지구 귀환 궤도에 진입했습니다!",[
('수직선 위의 점','비상 착륙 지점 확인','수직선 위 A(−4), B(8)의 한가운데에 있는 구조 신호기의 좌표를 입력하세요.',2,'두 좌표의 평균 (−4+8)/2=2입니다.','두 점의 좌표를 더해 2로 나누어요.'),
('순서쌍과 좌표','연료 캡슐 회수','(2a−1, 7)과 (5, b+3)이 같은 지점을 나타낼 때 a+b를 구하세요.',7,'2a−1=5에서 a=3, b+3=7에서 b=4이므로 합은 7입니다.','같은 점이면 x좌표끼리, y좌표끼리 같아요.'),
('x축·y축 위의 점','메인 안테나 정렬','점 P(a−4, a+3)이 x축 위에 있습니다. 점 P의 x좌표를 구하세요.',-7,'x축 위의 점은 y좌표가 0이므로 a+3=0, a=−3입니다. x좌표 a−4=−7입니다.','x축 위의 점은 y좌표가 0이에요.'),
('사분면의 이해','운석 지대 회피','A(−3, 5)가 속한 사분면을 제a사분면, B(4, −2)가 속한 사분면을 제b사분면이라 할 때 a+b를 구하세요.',6,'A는 제2사분면, B는 제4사분면이므로 2+4=6입니다.','사분면은 오른쪽 위부터 반시계 방향으로 1, 2, 3, 4예요.'),
('대칭인 점의 좌표','워프 게이트 좌표 변환','(3, −5)를 y축에 대해 대칭이동한 점을 (a, b)라 할 때 a−b를 입력하세요.',2,'대칭인 점은 (−3, −5)이므로 −3−(−5)=2입니다.','y축 대칭에서는 x좌표의 부호만 바뀌어요.'),
('좌표평면 위 도형의 넓이','태양광 패널 면적 계산','A(0, 4), B(−3, 0), C(5, 0)을 꼭짓점으로 하는 삼각형의 넓이를 구하세요.',16,'밑변 BC=8, 높이는 4이므로 넓이는 8×4÷2=16입니다.','BC는 x축 위에 있어요. 밑변 길이와 A에서 x축까지의 거리를 구하세요.','coordinate-triangle'),
('그래프의 해석','산소 탱크 압력 변화','이륙한 지 x분 후의 고도 ykm가 x에 정비례합니다. 3분 후 15km라면 7분 후의 고도(km)는 얼마인가요?',35,'1분에 5km씩 상승하므로 7분 후 고도는 35km입니다.','시간이 몇 배가 되면 고도도 같은 배수가 돼요.'),
('정비례 관계식','플라즈마 추진기 출력','y=ax의 그래프가 (−2, 8)을 지나고 (3, k)도 지납니다. k를 구하세요.',-12,'8=−2a에서 a=−4입니다. x=3이면 y=−4×3=−12입니다.','먼저 주어진 점으로 비례상수 a를 구해요.'),
('반비례 관계식','중력 제어 장치 세팅','y=a/x의 그래프가 (4, 6)을 지납니다. x=3일 때 y를 구하세요.',8,'a=4×6=24이므로 y=24/3=8입니다.','반비례 관계에서는 xy가 일정해요.'),
('정비례·반비례 그래프의 교점','지구 귀환 궤도 접속!','y=2x와 y=a/x가 (3, b)에서 만납니다. 최종 귀환 코드 a+b를 구하세요.',24,'b=2×3=6이고 6=a/3에서 a=18입니다. a+b=24입니다.','교점의 좌표는 두 식을 모두 만족해요.')])

game(6,'기본 도형과 위치 관계','레이저 보안망을 뚫어라! 미술관 야간 잠입 작전','🚨','laser',
"억울하게 도난당한 가문의 명화를 되찾기 위해 한밤중 미술관에 잠입했습니다. 얽혀 있는 직선 레이저의 각도와 위치 관계를 계산해 명화 보관실까지 돌파하세요!",
"삐비빅— 모든 레이저 보안망이 해제되었습니다! 명화를 무사히 품에 안고 미술관을 빠져나왔습니다.",[
('직선·반직선·선분','첫 번째 복도의 센서','일직선 위에 A, B, C, D가 이 순서로 놓여 있습니다. AD=18cm이고 AB=BC=CD일 때 AC의 길이(cm)를 구하세요.',12,'세 구간의 길이는 각각 18÷3=6cm입니다. AC는 두 구간이므로 12cm입니다.','전체 선분을 세 등분한 뒤 필요한 구간 수를 세어 보세요.','equal-segments'),
('중점과 선분의 길이','이중 보안문 열기','AB=24cm입니다. AB의 중점은 M, MB의 중점은 N일 때 AN의 길이(cm)를 구하세요.',18,'AM=12cm, MN=6cm이므로 AN=18cm입니다.','중점은 선분을 길이가 같은 두 부분으로 나눠요.','midpoints'),
('평각과 직각','천장 CCTV 사각지대','평각 180°를 나눈 세 각의 크기의 비가 2:3:4입니다. 가장 큰 각의 크기(도)를 입력하세요.',80,'180×4/(2+3+4)=80°입니다.','비의 합으로 전체 각도를 나눈 뒤 가장 큰 비를 곱해요.'),
('맞꼭지각의 성질','교차하는 붉은 레이저','두 직선이 만나 생긴 맞꼭지각 한 쌍의 크기가 (3x−10)°와 (x+40)°입니다. x를 구하세요.',25,'맞꼭지각은 같으므로 3x−10=x+40, 2x=50, x=25입니다.','맞꼭지각은 서로 마주 보는 같은 크기의 각이에요.'),
('수직과 수선','바닥 압력 센서 해제','직선 AB와 CD가 O에서 수직으로 만납니다. ∠AOC=(2x+10)°일 때 x를 구하세요.',40,'2x+10=90이므로 2x=80, x=40입니다.','수직으로 만나는 두 직선이 이루는 각은 90°예요.'),
('평행선과 동위각','나란히 뻗은 평행 레이저','평행한 두 직선을 한 직선이 가로지를 때 동위각 한 쌍의 크기가 115°와 (2x+15)°입니다. x를 구하세요.',50,'동위각은 같으므로 2x+15=115, x=50입니다.','평행한 두 직선에서 동위각의 크기는 같아요.'),
('평행선과 엇각','지그재그 거울 반사','그림에서 위아래 두 직선은 평행합니다. 두 선분이 왼쪽 위·아래에서 가운데 점으로 이어집니다. 위쪽 직선과 선분의 예각은 35°, 아래쪽 직선과 선분의 예각은 45°입니다. 가운데 두 선분이 이루는 왼쪽 각 x의 크기(도)를 구하세요.',80,'꺾인 점을 지나 평행한 보조선을 그으면 엇각이 각각 35°, 45°입니다. x=35+45=80°입니다.','꺾인 점을 지나고 두 직선에 평행한 보조선을 그어 보세요.','parallel-bend'),
('평면에서의 위치 관계','전시실 기둥 배치도','정육각형 ABCDEF에서 선분 AB와 평행한 다른 변의 개수를 a, 선분 AB와 끝점을 공유하는 이웃한 변의 개수를 b라 할 때 a+b를 구하세요. 변을 연장하지 않고 생각하세요.',3,'AB와 평행한 변은 DE 1개, 끝점을 공유하는 변은 AF와 BC 2개입니다. 합은 3입니다.','서로 마주 보는 변과 이웃한 변을 구분해요.','hexagon'),
('공간에서 꼬인 위치','유리 진열장 프레임','직육면체에서 모서리 AB와 꼬인 위치에 있는 모서리는 모두 몇 개인가요?',4,'전체 12개에서 AB 자신 1개, AB와 만나는 4개, 평행한 3개를 빼면 4개입니다.','꼬인 위치의 두 직선은 만나지도 평행하지도 않으며 같은 평면 위에 놓이지 않아요.','cuboid'),
('공간에서 직선·평면의 관계','명화 보관함 잠금 해제!','그림의 직육면체에서 밑면 EFGH에 수직인 모서리 수를 x, 밑면과 만나지 않고 평행한 모서리 수를 y라 할 때 x+y를 구하세요.',8,'기둥 모서리 AE, BF, CG, DH가 수직이고, 윗면의 네 모서리는 밑면과 평행합니다. 4+4=8입니다.','밑면에 포함되는 모서리는 평면과 평행한 모서리로 세지 않아요.','cuboid')])

game(7,'작도와 합동','잃어버린 고대 건축가의 설계도를 복원하라','📐','garden',
"전설적인 공중정원의 설계도가 찢어졌습니다! 눈금 없는 자와 컴퍼스를 사용하는 고대 작도법과 삼각형의 합동 원리로 설계도를 복원하세요!",
"와아아—! 복원된 설계도가 빛을 내며 공중정원의 비밀 문이 열렸습니다! 위대한 수석 건축가로 임명되었습니다.",[
('작도의 기본 도구','건축가의 도구함','① 각도기  ② 눈금 없는 자  ③ 삼각자  ④ 컴퍼스\n선분의 길이를 다른 직선 위로 옮길 때 사용하는 도구의 번호를 입력하세요.',4,'컴퍼스의 벌어진 폭에 길이를 담아 그대로 옮길 수 있습니다. 정답은 ④입니다.','길이를 직접 재지 않고도 같은 길이를 옮길 수 있는 도구를 찾아요.'),
('각의 이동 작도','성문 아치 각도 복사','같은 크기의 각을 작도하는 마지막 단계에서 두 점을 지나 각의 한 변인 반직선을 그립니다. 1: 눈금 없는 자, 2: 컴퍼스 중 사용할 도구의 번호는?',1,'두 점을 연결해 직선이나 반직선을 그을 때 눈금 없는 자를 사용합니다.','원을 그리는 도구와 곧은 선을 그리는 도구를 구분하세요.'),
('삼각형의 세 변 조건','무너지지 않는 지붕 트러스','4m, 9m, xm인 세 기둥으로 삼각형을 만듭니다. x가 될 수 있는 자연수 중 가장 작은 수는?',6,'9−4<x<9+4에서 5<x<13이므로 가장 작은 자연수는 6입니다.','가장 긴 변은 나머지 두 변의 길이의 합보다 짧아야 해요.'),
('삼각형의 세 변 조건 응용','목재 고르기','길이가 3, 4, 6, 9인 목재 중 서로 다른 3개를 골라 만들 수 있는 삼각형은 몇 가지인가요?',2,'(3,4,6), (4,6,9)는 가능하고, (3,4,9), (3,6,9)는 불가능합니다. 모두 2가지입니다.','세 목재의 조합을 나열하고 짧은 두 변의 합을 확인하세요.'),
('삼각형이 하나로 결정되는 조건','완벽한 설계 치수','삼각형 ABC에서 AB=5, BC=7입니다. 두 변과 그 끼인각으로 삼각형을 결정하려면 어느 각이 필요할까요? 1: ∠A, 2: ∠B, 3: ∠C',2,'두 변 AB와 BC가 만나는 꼭짓점은 B이므로 끼인각은 ∠B입니다.','두 변이 함께 가지는 꼭짓점을 찾으세요.'),
('도형의 합동 성질','쌍둥이 석판 맞추기','사각형 ABCD와 EFGH가 이 순서로 대응하여 합동입니다. AB=8, FG=11, ∠C=75°, ∠H=100°일 때 BC의 길이와 ∠G의 크기의 합을 구하세요.',86,'BC는 FG에 대응하므로 11, ∠G는 ∠C에 대응하므로 75°입니다. 11+75=86입니다.','합동 기호에 쓰인 꼭짓점의 순서에 따라 대응시켜 보세요.'),
('SSS 합동','첫 번째 기둥의 문양','1: SSS, 2: SAS, 3: ASA 중 대응하는 세 변의 길이가 각각 같을 때의 합동 조건 번호를 입력하세요.',1,'세 변의 길이가 각각 같은 조건은 SSS 합동입니다.','S는 변, A는 각을 나타내요.'),
('SAS 합동 응용','정삼각형 제단의 각도','정삼각형 ABC의 변 AB, BC, CA 위에 각각 D, E, F를 잡고 AD=BE=CF가 되게 했습니다. 세 모서리의 작은 삼각형은 SAS 합동이므로 삼각형 DEF도 정삼각형입니다. ∠DEF의 크기(도)는?',60,'정삼각형의 세 내각은 같고 합이 180°이므로 각각 60°입니다.','합동에서 대응변이 같음을 이용하면 안쪽 삼각형도 정삼각형임을 알 수 있어요.','inscribed-triangle'),
('ASA 합동','강 건너 탑까지의 거리 측량','탑까지의 거리는 선분 AC입니다. 강가에 삼각형 DEF를 만들어 ∠A=∠D, ∠B=∠E, AB=DE가 되게 했습니다. 대응변 DF의 길이가 45m라면 탑까지의 거리 AC(m)는?',45,'한 변과 그 양 끝 각이 각각 같아 ASA 합동입니다. AC에 대응하는 DF가 45m이므로 AC도 45m입니다.','삼각형 ABC와 DEF에서 A↔D, B↔E, C↔F가 대응해요.'),
('합동을 이용한 각도 추론','공중정원의 마지막 열쇠!','정사각형과 정삼각형을 배치한 설계도에서 합동을 이용하여 꼭지각이 30°인 이등변삼각형을 찾았습니다. 이 삼각형의 한 밑각의 크기(도)를 구하세요.',75,'두 밑각은 같으므로 (180−30)÷2=75°입니다.','삼각형의 내각의 합은 180°이고 이등변삼각형의 두 밑각은 같아요.','isosceles')])

game(8,'다각형과 원','시계탑 톱니바퀴의 멈춰버린 시간을 돌려라','⚙️','clock',
"마을 한가운데 거대한 마법 시계탑이 멈췄습니다! 다각형 톱니바퀴와 부채꼴 태엽의 각도·넓이를 계산해 시계탑의 심장을 다시 뛰게 하세요!",
"째깍, 째깍, 땡—! 시계탑의 종소리가 마을 전체에 울려 퍼집니다! 멈췄던 시간이 다시 흐르기 시작했습니다.",[
('다각형의 대각선 개수','첫 번째 톱니바퀴의 강철 줄','팔각형 톱니바퀴의 모든 대각선에 강철 줄을 연결합니다. 대각선은 몇 개인가요?',20,'n각형의 대각선 수는 n(n−3)/2입니다. 8×5/2=20개입니다.','한 꼭짓점에서 연결할 수 있는 대각선 수를 생각하고 중복을 빼세요.'),
('삼각형의 내각과 외각','시계추의 진자 각도','삼각형 ABC에서 ∠A=55°, ∠B=65°일 때 ∠C의 외각의 크기(도)를 구하세요.',120,'한 외각은 이웃하지 않는 두 내각의 합이므로 55+65=120°입니다.','∠C를 먼저 구한 뒤 180°에서 빼도 돼요.'),
('다각형 내각의 합','육각 너트 조이기','육각형 너트의 여섯 내각의 크기의 합(도)을 입력하세요.',720,'180×(6−2)=720°입니다.','n각형은 한 꼭짓점에서 n−2개의 삼각형으로 나눌 수 있어요.'),
('다각형 외각의 합','회전하는 외곽 기어','볼록한 십이각형 기어에서 각 꼭짓점의 한 외각을 같은 방향으로 잡았습니다. 외각의 합(도)은?',360,'볼록다각형에서 한 바퀴 도는 외각의 합은 360°입니다.','변의 개수가 달라도 한 바퀴 회전한 각도는 같아요.'),
('정다각형의 내각과 외각','정십각형 톱니 각도','정십각형의 한 내각의 크기(도)를 구하세요.',144,'한 외각은 360÷10=36°이므로 한 내각은 180−36=144°입니다.','한 내각과 그 외각의 합은 180°예요.'),
('중심각과 호의 길이','태엽 스프링 장력','같은 원에서 중심각 40°인 부채꼴의 호 길이가 6cm입니다. 중심각 120°인 부채꼴의 호 길이(cm)는?',18,'중심각이 3배가 되었으므로 호의 길이도 6×3=18cm입니다.','같은 원에서 호의 길이는 중심각에 정비례해요.'),
('중심각과 현의 성질','함정 질문 주의!','한 원에서 중심각을 키우면 현의 길이도 중심각에 정비례할까요? 1: 정비례한다, 2: 정비례하지 않는다',2,'호의 길이와 부채꼴 넓이는 중심각에 정비례하지만, 현의 길이는 정비례하지 않습니다.','현은 원 위의 두 점을 잇는 곧은 선분이에요. 호와 구분하세요.'),
('원주와 원의 넓이','거대 시계판의 테두리','반지름 7cm인 원의 둘레가 aπcm일 때 a를 구하세요.',14,'원주=2πr=14πcm이므로 a=14입니다.','원의 둘레는 지름×π예요.'),
('부채꼴의 호의 길이와 넓이','황금 진자의 궤적','반지름 6cm, 중심각 60°인 부채꼴의 넓이가 kπcm²입니다. k를 구하세요.',6,'π×6²×60/360=6πcm²이므로 k=6입니다.','원의 넓이에 중심각/360을 곱해요.','sector'),
('반지름과 호로 넓이 구하기','시계탑 심장 재가동!','반지름 8cm, 호의 길이 5πcm인 부채꼴의 넓이가 Sπcm²일 때 S를 구하세요.',20,'부채꼴의 넓이=(1/2)×반지름×호의 길이=(1/2)×8×5π=20πcm²입니다.','반지름과 호의 길이를 알 때 넓이=(1/2)rl을 이용하세요.')])

game(9,'입체도형','달콤 초콜릿 공장, 황금 포장지를 찾아서','🍫','chocolate',
"윌리 웡카의 달콤 초콜릿 공장에 초대받았습니다! 초콜릿 틀의 부피와 포장지 겉넓이를 계산한 사람만이 전설의 ‘황금 포장지’를 얻을 수 있습니다!",
"축하합니다! 반짝이는 황금 포장지 초콜릿이 눈앞에 나타났습니다! 공장의 최고 쇼콜라티에로 인정받았습니다.",[
('각기둥의 면·꼭짓점','육각기둥 초콜릿 상자','육각기둥의 면의 개수를 f, 꼭짓점의 개수를 v라 할 때 f+v를 구하세요.',20,'면은 6+2=8개, 꼭짓점은 6×2=12개이므로 합은 20입니다.','위아래 밑면과 옆면을 나누어 세어 보세요.'),
('각뿔대','잘린 피라미드 트러플','오각뿔대의 옆면 모양은 무엇인가요? 1: 직사각형, 2: 사다리꼴, 3: 마름모',2,'각뿔을 밑면과 평행하게 잘라 만든 각뿔대의 옆면은 사다리꼴입니다.','각뿔의 삼각형 옆면에서 꼭대기 부분을 평행하게 잘라 보세요.'),
('정다면체의 종류','5가지 보석 사탕','다섯 가지 정다면체 중 각 면이 정오각형이고 한 꼭짓점에 세 면이 모이는 정다면체의 면의 개수를 입력하세요.',12,'각 면이 정오각형인 정다면체는 정십이면체이며 면은 12개입니다.','정사면체·정육면체·정팔면체·정십이면체·정이십면체의 면 모양을 떠올려 보세요.'),
('회전체의 단면','딸기 크림 원뿔 케이크','원뿔을 회전축을 포함하는 평면으로 자른 단면은? 1: 원, 2: 직사각형, 3: 이등변삼각형',3,'회전축을 포함하여 자르면 두 모선의 길이가 같은 이등변삼각형이 됩니다.','꼭짓점과 밑면의 지름을 지나는 단면을 생각하세요.'),
('원뿔의 전개도','고깔모자 포장지','모선 10cm, 밑면 반지름 4cm인 원뿔의 옆면을 펼쳤습니다. 부채꼴의 호 길이가 aπcm일 때 a는?',8,'옆면 부채꼴의 호는 밑면의 원주와 같으므로 2π×4=8πcm입니다.','모선은 부채꼴의 반지름이고, 호는 밑면 원의 둘레와 이어져요.'),
('기둥의 겉넓이','큐브 브라우니 포장','가로 3cm, 세로 4cm, 높이 5cm인 직육면체의 겉넓이(cm²)를 구하세요.',94,'2×(3×4+3×5+4×5)=2×47=94cm²입니다.','서로 같은 면이 세 쌍 있어요.','cuboid-dimensions'),
('기둥의 부피','핫초코 원기둥 탱크','밑면 반지름 3cm, 높이 6cm인 원기둥의 부피가 Vπcm³입니다. V를 구하세요.',54,'밑넓이×높이=π×3²×6=54πcm³이므로 V=54입니다.','원기둥의 밑면은 원이에요.'),
('뿔의 겉넓이','피라미드 골드 초콜릿','밑면이 한 변 6cm인 정사각형이고, 옆면 삼각형의 높이가 5cm인 정사각뿔의 겉넓이(cm²)는?',96,'밑넓이 36에 옆넓이 (1/2×6×5)×4=60을 더하면 96cm²입니다.','주어진 5cm는 뿔 전체의 높이가 아니라 옆면 삼각형의 높이예요.'),
('뿔의 부피','다크초코 콘 채우기','밑넓이 15cm², 높이 8cm인 사각뿔의 부피(cm³)를 구하세요.',40,'(1/3)×15×8=40cm³입니다.','뿔의 부피는 밑넓이×높이의 1/3이에요.'),
('구의 겉넓이와 부피','전설의 황금 초콜릿 볼 완성!','반지름 3cm인 구의 겉넓이가 Aπcm², 부피가 Bπcm³일 때 A+B를 구하세요.',72,'겉넓이 4π×3²=36π, 부피 (4/3)π×3³=36π이므로 A+B=72입니다.','구의 겉넓이=4πr², 부피=(4/3)πr³을 각각 계산해요.')])

game(10,'자료의 정리와 해석','AI 범죄예측 본부, 빅데이터 속 스파이를 찾아라','💻','data',
"국가정보원 AI 빅데이터 본부에 이중 스파이가 침투해 데이터를 조작했습니다! 줄기와 잎 그림, 도수분포표, 상대도수 기록을 분석해 스파이의 ID를 특정하세요!",
"삐빅— 스파이 신원 확인 완료! 모든 보안 데이터가 정상 복구되었습니다! 중학교 1학년 수학 10단계 방탈출 대장정을 모두 완벽하게 클리어했습니다!",[
('변량과 줄기와 잎 그림','출입 기록 로그 분석','접속 횟수는 12, 15, 21, 24, 24, 28, 31입니다. 십의 자리를 줄기로 할 때 줄기가 2인 잎의 개수는?',4,'21, 24, 24, 28의 잎 1, 4, 4, 8이므로 모두 4개입니다. 같은 값도 각각 셉니다.','20 이상 30 미만인 자료를 빠짐없이 세어 보세요.'),
('도수분포표와 계급의 크기','암호 해독 시간 표','해독 시간을 10초 이상~20초 미만, 20초 이상~30초 미만으로 나눴습니다. 계급의 크기(초)는?',10,'계급의 크기는 계급의 양 끝 값의 차이이므로 20−10=10초입니다.','한 계급의 끝 값에서 시작 값을 빼세요.'),
('계급값 구하기','의심 구간의 중심값','40분 이상~60분 미만인 계급의 계급값(분)을 구하세요.',50,'계급값=(40+60)/2=50분입니다.','계급값은 계급 양 끝 값의 평균이에요.'),
('도수의 총합과 미지수','삭제된 인원수 복구','전체 30명의 네 계급 도수가 각각 5명, 12명, x명, 4명입니다. x를 구하세요.',9,'30−(5+12+4)=9명입니다.','모든 계급의 도수를 더하면 전체 인원수가 돼요.'),
('히스토그램 직사각형의 넓이','서버 트래픽 그래프','계급의 크기가 모두 5이고 도수의 총합이 20인 히스토그램에서 모든 직사각형의 넓이의 합은?',100,'계급의 크기×도수의 총합=5×20=100입니다.','각 직사각형의 가로는 계급의 크기, 세로는 도수예요.'),
('도수분포다각형의 넓이','숨겨진 데이터 면적','앞 문제의 히스토그램 직사각형 넓이의 합은 100입니다. 윗변의 중점을 연결하고, 양 끝에 도수 0인 계급을 하나씩 추가해 가로축까지 이은 도수분포다각형과 가로축 사이의 넓이는?',100,'양 끝을 도수 0인 계급까지 이어 닫으면, 빠져나간 삼각형과 더해진 삼각형의 넓이가 같아 히스토그램의 넓이와 같습니다. 따라서 100입니다.','중점으로 나뉜 삼각형들을 옮겨 보면 전체 넓이가 보존돼요.'),
('상대도수의 성질','전체 확률 코드','모든 계급의 상대도수를 더하면 얼마인가요?',1,'각 상대도수는 도수/전체 도수이므로 합은 전체 도수/전체 도수=1입니다.','모든 계급을 합치면 전체 자료가 돼요.'),
('상대도수로 도수 구하기','용의자 그룹 인원 산출','전체 요원 50명 중 특정 계급의 상대도수가 0.16입니다. 이 계급에 속한 인원수는?',8,'50×0.16=8명입니다.','도수=전체 도수×상대도수예요.'),
('도수와 상대도수로 전체 구하기','본부 총원 파악','도수가 6명인 계급의 상대도수가 0.15일 때 전체 인원수는?',40,'전체 도수=6÷0.15=40명입니다.','상대도수=도수/전체 도수인 식을 바꿔 보세요.'),
('두 집단의 상대도수 비교','스파이의 최종 ID 검거!','A팀은 전체 40명, B팀은 전체 60명입니다. 야간 접속 계급의 상대도수가 두 팀 모두 0.25일 때 그 계급에 속한 두 팀 인원수의 합은?',25,'A팀은 40×0.25=10명, B팀은 60×0.25=15명이므로 합은 25명입니다.','상대도수가 같아도 전체 인원이 다르면 해당 도수는 다를 수 있어요.')])

Path(__file__).with_name('math_quest_adventures.json').write_text(json.dumps(games,ensure_ascii=False,indent=2),encoding='utf-8')
